-- ==============================================================================
-- MITRA DELIVERY CONFIRMATION PLATFORM — STANDALONE SAMPLE SEED DATA
-- ==============================================================================
-- Run this script directly in the Supabase SQL Editor at any time to reload 
-- 5 months of realistic multi-vendor delivery records, absent days, and disputes.
-- This script associates the sample data with your active primary household.
-- ==============================================================================

DO $$
DECLARE
    target_hh_id UUID;
    v1_id UUID := '00000000-0000-0000-0000-000000000001';
    v2_id UUID := '00000000-0000-0000-0000-000000000002';
    v3_id UUID := '00000000-0000-0000-0000-000000000003';
BEGIN
    -- 1. Locate primary household
    SELECT id INTO target_hh_id FROM households ORDER BY created_at ASC LIMIT 1;
    IF target_hh_id IS NULL THEN
        VALUES ('Primary Household', 'en', false, 24)
        RETURNING id INTO target_hh_id;
    END IF;

    -- 2. Temporarily disable trigger for bulk historical seed
    ALTER TABLE entries DISABLE TRIGGER trigger_enforce_tamper_proof_status;

    -- 3. Upsert Sample Vendors
    ON CONFLICT (id) DO UPDATE SET
        name = EXCLUDED.name,
        phone_number = EXCLUDED.phone_number,
        is_active = true;

    -- 4. Upsert Sample Products
    ON CONFLICT (id) DO UPDATE SET
        name = EXCLUDED.name,
        default_price = EXCLUDED.default_price;

    -- 5. Insert Sample Delivery Entries (126 rows)
    ON CONFLICT (id) DO UPDATE SET
        quantity = EXCLUDED.quantity,
        total_price = EXCLUDED.total_price,
        status = EXCLUDED.status;

    -- 6. Re-enable trigger
    ALTER TABLE entries ENABLE TRIGGER trigger_enforce_tamper_proof_status;

    RAISE NOTICE 'Mitra sample seed successfully applied for household %', target_hh_id;
END $$;
